mapper.sql:
FROM users u WHERE u.deleted_at IS NULL
AND (u.username LIKE '%' || #{params.keyword} || '%' OR u.email LIKE '%' || #{params.keyword} || '%' OR u.nickname LIKE '%' || #{params.keyword} || '%')
AND u.status = #{params.status}
AND (EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id = u.id AND ur.role_id = #{params.roleId}) OR EXISTS (SELECT 1 FROM department_roles dr JOIN user_departments ud ON ud.department_id = dr.department_id WHERE ud.user_id = u.id AND dr.role_id = #{params.roleId}))
AND EXISTS (SELECT 1 FROM user_departments ud WHERE ud.user_id = u.id AND ud.department_id = #{params.departmentId})
AND u.created_at >= #{params.createdAtStart}
AND u.created_at <= #{params.createdAtEnd}

mapper.select:
SELECT id, name, code, description, status, level,
       landing_page as landingPage, created_at as createdAt, updated_at as updatedAt
FROM roles WHERE id = #{id}

SELECT u.id, u.username, u.nickname, u.email, u.avatar, u.status,
       u.created_at as createdAt, u.updated_at as updatedAt


    ORDER BY ${params.sort}


    ORDER BY u.id DESC

LIMIT #{params.limit} OFFSET #{params.offset}


WHERE u.id IN

    #{id}

AND u.deleted_at IS NULL

mapper.update:
UPDATE users SET
${col} = #{val}
, updated_at = datetime('now') WHERE id = #{id} AND deleted_at IS NULL
